import pysnooper.utils as utils


def test_get_shortish_repr_removes_carriage_returns_and_newlines():
    result = utils.get_shortish_repr(
        object(),
        custom_repr=((lambda item: True, lambda item: "first\r\nsecond"),),
    )

    assert result == "firstsecond"


def test_get_shortish_repr_normalizes_repr():
    result = utils.get_shortish_repr(
        object(),
        custom_repr=(
            (lambda item: True, lambda item: "<Example object at 0xABCDEF>"),
        ),
        normalize=True,
    )

    assert result == "<Example object>"


def test_get_shortish_repr_returns_failure_marker_when_repr_raises():
    def failing_repr(item):
        raise RuntimeError("representation failed")

    result = utils.get_shortish_repr(
        object(),
        custom_repr=((lambda item: True, failing_repr),),
    )

    assert result == "REPR FAILED"


def test_get_shortish_repr_truncates_when_max_length_is_truthy():
    result = utils.get_shortish_repr(
        object(),
        custom_repr=((lambda item: True, lambda item: "abcdefghij"),),
        max_length=7,
    )

    assert result == "ab...ij"
