from pysnooper.utils import WritableStream


def test_writable_stream_abstract_write_returns_none():
    class ConcreteWritableStream(WritableStream):
        def write(self, s):
            return "implemented"

    stream = ConcreteWritableStream()

    assert WritableStream.write(stream, "data") is None


def test_writable_stream_subclasshook_checks_for_write_method():
    class HasWrite:
        def write(self, s):
            return None

    class WithoutWrite:
        pass

    assert WritableStream.__subclasshook__(HasWrite) is True
    assert WritableStream.__subclasshook__(WithoutWrite) is NotImplemented


def test_writable_stream_subclasshook_returns_not_implemented_for_subclasses():
    class DerivedWritableStream(WritableStream):
        def write(self, s):
            return None

    class HasWrite:
        def write(self, s):
            return None

    assert DerivedWritableStream.__subclasshook__(HasWrite) is NotImplemented
